# Original 256x96 PNG and editable SVG: green source, gold distribution, blue consumer.
width, height = 256, 96
pixels = bytearray([23, 44, 49, 255] * width * height)
def rect(x0, y0, x1, y1, color):
    for y in range(y0, y1):
        for x in range(x0, x1):
            p = (y * width + x) * 4
            pixels[p:p + 4] = bytes(color)
for x, color in ((16, (138, 213, 174, 255)), (104, (240, 202, 130, 255)), (192, (139, 190, 224, 255))):
    rect(x, 22, x + 48, 74, color)
    for dx in range(8, 41, 12):
        rect(x + dx, 34, x + dx + 5, 62, (23, 44, 49, 255))
for x in (68, 156):
    rect(x, 45, x + 28, 51, (234, 241, 248, 255))
    for n in range(10):
        rect(x + 20 + n, 38 + n, x + 21 + n, 58 - n, (234, 241, 248, 255))
def chunk(name, payload):
    return struct.pack('!I', len(payload)) + name + payload + struct.pack('!I', zlib.crc32(name + payload) & 0xffffffff)
rows = b''.join(b'\0' + bytes(pixels[y * width * 4:(y + 1) * width * 4]) for y in range(height))
png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('!2I5B', width, height, 8, 6, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(rows)) + chunk(b'IEND', b'')
image = ROOT / 'assets/frontier_industry/textures/gui/guide/power_chain.png'
image.parent.mkdir(parents=True, exist_ok=True)
image.write_bytes(png)
Path(__file__).with_name('power_chain.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 96"><rect width="256" height="96" fill="#172c31"/><path d="M16 22h48v52H16z" fill="#8ad5ae"/><path d="M104 22h48v52h-48z" fill="#f0ca82"/><path d="M192 22h48v52h-48z" fill="#8bbee0"/><path d="M68 48h28m60 0h28" stroke="#eaf1f8" stroke-width="6"/></svg>\n')
print('Exported Russian field guide: 4 categories, 11 entries, en_us fallback + ru_ru, original diagram.')
